function GatewayFlow({className=""}){const canvasRef=useRef(null);useEffect(()=>{const canvas=canvasRef.current;if(!canvas)return;const parent=canvas.parentElement;const ctx=canvas.getContext("2d");if(!ctx||!parent)return;let width=0,height=0,frame=0;let paths=[];const resize=()=>{const rect=parent.getBoundingClientRect();width=Math.max(1,rect.width);height=Math.max(1,rect.height);const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);canvas.style.width=width+"px";canvas.style.height=height+"px";ctx.setTransform(dpr,0,0,dpr,0,0);const count=Math.max(34,Math.min(74,Math.round(width/16)));paths=Array.from({length:count},(_,index)=>{const side=index%2===0?-1:1;const normalized=Math.floor(index/2)/Math.max(1,Math.ceil(count/2)-1);return{side,y:height*(.05+normalized*.9),phase:Math.random(),speed:.00010+Math.random()*.00015,offset:(Math.random()-.5)*8}})};const point=(t,side,y)=>{const centerX=width*.5,centerY=height*.5,edgeX=side<0?-width*.08:width*1.08,nearX=side<0?width*.26:width*.74,p0={x:edgeX,y},p1={x:side<0?width*.22:width*.78,y},p2={x:nearX,y:centerY+(y-centerY)*.58},p3={x:centerX,y:centerY},u=1-t;return{x:u**3*p0.x+3*u**2*t*p1.x+3*u*t**2*p2.x+t**3*p3.x,y:u**3*p0.y+3*u**2*t*p1.y+3*u*t**2*p2.y+t**3*p3.y}};const draw=time=>{ctx.clearRect(0,0,width,height);const centerX=width*.5,centerY=height*.5;const vignette=ctx.createRadialGradient(centerX,centerY,0,centerX,centerY,width*.58);vignette.addColorStop(0,"rgba(255,255,255,.035)");vignette.addColorStop(.34,"rgba(0,0,0,0)");vignette.addColorStop(1,"rgba(0,0,0,.24)");ctx.fillStyle=vignette;ctx.fillRect(0,0,width,height);paths.forEach((path,pathIndex)=>{const left=path.side<0,y=path.y+Math.sin(time*.00035+pathIndex)*1.7,p0={x:left?-width*.08:width*1.08,y},p1={x:left?width*.22:width*.78,y:y+path.offset},p2={x:left?width*.78:width*.22,y:centerY+(y-centerY)*.58},p3={x:centerX,y:centerY};ctx.beginPath();ctx.moveTo(p0.x,p0.y);ctx.bezierCurveTo(p1.x,p1.y,p2.x,p2.y,p3.x,p3.y);ctx.strokeStyle="rgba(139,92,246,.20)";ctx.lineWidth=.65;ctx.setLineDash([1,5]);ctx.stroke();ctx.setLineDash([]);for(let j=0;j<5;j++){const t=(path.phase+time*path.speed+j/3)%1,pos=point(t,path.side,y),pulse=.55+.45*Math.sin(time*.0012+pathIndex*1.7+j),radius=.75+pulse*.75;ctx.fillStyle="rgba(139,92,246,"+(.38+pulse*.28)+")";ctx.fillRect(pos.x-radius,pos.y-radius,radius*2,radius*2)}});for(let i=0;i<70;i++){const side=i%2===0?-1:1,spread=i/69*2-1,pulse=(Math.sin(time*.00055+i*1.91)+1)*.5,radiusX=width*(.07+pulse*.015),radiusY=height*(.08+pulse*.03),x=centerX+side*radiusX,y=centerY+spread*radiusY;ctx.fillStyle="rgba(104,76,180,"+(.15+pulse*.22)+")";ctx.fillRect(x,y,1.4,1.4)}const core=ctx.createRadialGradient(centerX,centerY,0,centerX,centerY,42);core.addColorStop(0,"rgba(196,181,253,.72)");core.addColorStop(.16,"rgba(139,92,246,.28)");core.addColorStop(.48,"rgba(34,211,238,.08)");core.addColorStop(1,"rgba(0,0,0,0)");ctx.fillStyle=core;ctx.fillRect(centerX-32,centerY-32,64,64);frame=requestAnimationFrame(draw)};const observer=new ResizeObserver(resize);observer.observe(parent);resize();frame=requestAnimationFrame(draw);return()=>{observer.disconnect();cancelAnimationFrame(frame)}},[]);return <div className={className} aria-hidden="true" style={{position:"absolute",inset:0,width:"100%",height:"100%",margin:0,overflow:"hidden",background:"transparent",opacity:.64}}><canvas ref={canvasRef} style={{display:"block",width:"100%",height:"100%"}}/><div style={{position:"absolute",inset:0,pointerEvents:"none",background:"radial-gradient(ellipse at center,transparent 16%,rgba(2,2,2,.08) 54%,rgba(2,2,2,.62) 100%),linear-gradient(180deg,rgba(2,2,2,.12),transparent 32%,transparent 70%,rgba(2,2,2,.5))"}}/></div>}


