async function getProcessingTicket({workspaceId,projectId,sourceId,jobId,mediaAssetId}){const refreshed=await supabase.auth.refreshSession();let session=refreshed.data?.session||null;if(!session?.access_token){const fallback=await supabase.auth.getSession();session=fallback.data?.session||null}if(!session?.access_token)throw new Error("Your sign-in session expired. Please sign in again and retry the upload.");const response=await fetch("/api/import-ticket",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+session.access_token},body:JSON.stringify({workspaceId,projectId,sourceId,jobId,mediaAssetId})});const body=await response.json().catch(()=>({}));if(!response.ok||!body.ticket)throw new Error(body.error||"Could not authorize the processing job.");return body.ticket}
async function handleUpload(file){
  if(!supabase||!user||!workspace||!file)return;
  setBusy(true);setProgress(1);setUploadMsg("");
  if(file.size>5*1024*1024*1024){setUploadMsg("Maximum source size is 5 GB.");setBusy(false);return}
  if(!file.type.startsWith("video/")){setUploadMsg("Please choose a video file.");setBusy(false);return}
  const clean=file.name.replace(/[^a-zA-Z0-9._-]/g,"-"),projectName=file.name.replace(/\\.[^.]+$/,"").slice(0,80)||"Untitled video";
  const pr=await supabase.from("projects").insert({workspace_id:workspace.id,owner_id:user.id,name:projectName,status:"uploading"}).select().single();
  if(pr.error){setUploadMsg(pr.error.message);setBusy(false);return}
  const project=pr.data,path=workspace.id+"/"+project.id+"/"+crypto.randomUUID()+"-"+clean;
  const asset=await supabase.from("media_assets").insert({workspace_id:workspace.id,project_id:project.id,owner_id:user.id,name:file.name,storage_path:path,mime_type:file.type,size_bytes:file.size,status:"uploading"}).select().single();
  if(asset.error){setUploadMsg(asset.error.message);setBusy(false);return}
  const video=await supabase.from("videos").insert({project_id:project.id,media_asset_id:asset.data.id,title:projectName,status:"uploading"}).select().single();
  if(video.error){setUploadMsg(video.error.message);setBusy(false);return}
  const src=await supabase.from("project_sources").insert({workspace_id:workspace.id,project_id:project.id,source_type:"upload",file_name:file.name,status:"uploading",metadata:{mime_type:file.type,size:file.size}}).select().single();
  if(src.error){setUploadMsg(src.error.message);setBusy(false);return}
  const job=await supabase.from("processing_jobs").insert({workspace_id:workspace.id,project_id:project.id,job_type:"ingest",status:"queued",progress:0,payload:{media_asset_id:asset.data.id,video_id:video.data.id,source_id:src.data.id}}).select().single();
  if(job.error){setUploadMsg(job.error.message);setBusy(false);return}
  let processingTicket="";
  try{processingTicket=await getProcessingTicket({workspaceId:workspace.id,projectId:project.id,sourceId:src.data.id,jobId:job.data.id,mediaAssetId:asset.data.id})}
  catch(error){setUploadMsg(error?.message||"Could not authorize the processing job.");setBusy(false);return}
  const sessionData=await supabase.auth.getSession(),session=sessionData.data?.session;
  if(!session?.access_token){setUploadMsg("Your sign-in session expired. Please sign in again and retry the upload.");setBusy(false);return}
  const supabaseUrl=process.env.NEXT_PUBLIC_SUPABASE_URL||"",projectId=new URL(supabaseUrl).hostname.split(".")[0],anonKey=process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY||process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY||"",endpoint="https://"+projectId+".storage.supabase.co/storage/v1/upload/resumable";
  const ok=await new Promise(resolve=>{try{const upload=new tus.Upload(file,{endpoint,retryDelays:[0,2000,5000,10000,20000,30000,45000,60000],headers:{authorization:"Bearer "+session.access_token,apikey:anonKey,"x-upsert":"true"},uploadDataDuringCreation:true,removeFingerprintOnSuccess:true,chunkSize:4*1024*1024,metadata:{bucketName:"media",objectName:path,contentType:file.type,cacheControl:"3600"},onError:error=>{console.error("TUS upload failed",error);resolve(false)},onProgress:(bytes,total)=>{setProgress(Math.max(2,Math.round((bytes/total)*84)))},onSuccess:()=>resolve(true)});upload.findPreviousUploads().then(previous=>{if(previous.length)upload.resumeFromPreviousUpload(previous[0]);upload.start()}).catch(error=>{console.error("TUS resume failed",error);resolve(false)})}catch(error){console.error("TUS init failed",error);resolve(false)}});
  if(!ok){await supabase.from("processing_jobs").update({status:"failed",error:"Resumable upload failed after automatic retries"}).eq("id",job.data.id);await supabase.from("project_sources").update({status:"failed"}).eq("id",src.data.id);await supabase.from("projects").update({status:"upload_failed"}).eq("id",project.id);setUploadMsg(navigator.onLine===false?"Your browser reports no internet connection. The resumable upload will work again when the connection returns.":"The video upload could not complete after automatic retries. Please retry; your upload uses 4 MB resumable chunks.");setBusy(false);return}
  setProgress(88);
  const assetUpdate=await supabase.from("media_assets").update({status:"uploaded"}).eq("id",asset.data.id);
  if(assetUpdate.error){setUploadMsg(assetUpdate.error.message);setBusy(false);return}
  const videoUpdate=await supabase.from("videos").update({status:"ready"}).eq("id",video.data.id);
  if(videoUpdate.error){setUploadMsg(videoUpdate.error.message);setBusy(false);return}
  await supabase.from("project_sources").update({status:"queued"}).eq("id",src.data.id);
  await supabase.from("projects").update({status:"processing"}).eq("id",project.id);
  await supabase.from("processing_logs").insert({job_id:job.data.id,level:"info",message:"Resumable source upload completed; ingest queued."});
  try{
    const response=await fetch("/api/import-source",{method:"POST",headers:{"Content-Type":"application/json","x-import-ticket":processingTicket},body:JSON.stringify({sourceType:"upload",workspaceId:workspace.id,projectId:project.id,sourceId:src.data.id,jobId:job.data.id,mediaAssetId:asset.data.id})});
    if(!response.ok){const body=await response.json().catch(()=>({}));await supabase.from("processing_jobs").update({status:"failed",error:body.error||"Media worker unavailable"}).eq("id",job.data.id);setUploadMsg(body.error||"Media worker is not connected.");setBusy(false);return}
  }catch(error){console.error(error);setUploadMsg(error?.message||"Could not reach the media worker.");setBusy(false);return}
  setProgress(100);setUploadMsg("Upload complete. Media processing has started.");setUploadDone("Your video is uploaded and the processing pipeline has started.");await loadProjects(workspace.id);setBusy(false);setUpload(false);setUploadMsg("");
}
async function handleSourceUrl(url){if(!supabase||!user||!workspace||!url.trim())return;setBusy(true);setProgress(5);setUploadMsg("");let source_type="direct_url";try{const u=new URL(url.trim());const host=u.hostname.toLowerCase();if(host.includes("youtube.com")||host.includes("youtu.be"))source_type="youtube";else if(host.includes("drive.google.com"))source_type="google_drive";else if(host.includes("dropbox.com"))source_type="dropbox";else if(host.includes("1drv.ms")||host.includes("onedrive.live.com"))source_type="onedrive";}catch{setUploadMsg("Please enter a valid URL.");setBusy(false);return}const name=(source_type==="youtube"?"YouTube":source_type==="google_drive"?"Google Drive":source_type==="dropbox"?"Dropbox":source_type==="onedrive"?"OneDrive":"Linked")+" source";const pr=await supabase.from("projects").insert({workspace_id:workspace.id,owner_id:user.id,name,status:"uploading"}).select().single();if(pr.error){setUploadMsg(pr.error.message);setBusy(false);return}const src=await supabase.from("project_sources").insert({workspace_id:workspace.id,project_id:pr.data.id,source_type,source_url:url.trim(),status:"queued",metadata:{url:url.trim()}}).select().single();if(src.error){setUploadMsg(src.error.message);setBusy(false);return}const job=await supabase.from("processing_jobs").insert({workspace_id:workspace.id,project_id:pr.data.id,job_type:"ingest",status:"queued",progress:0,payload:{source_type,source_id:src.data.id,url:url.trim()}}).select().single();if(job.error){setUploadMsg(job.error.message);setBusy(false);return}try{const processingTicket=await getProcessingTicket({workspaceId:workspace.id,projectId:pr.data.id,sourceId:src.data.id,jobId:job.data.id});const response=await fetch("/api/import-source",{method:"POST",headers:{"Content-Type":"application/json","x-import-ticket":processingTicket},body:JSON.stringify({url:url.trim(),sourceType:source_type,workspaceId:workspace.id,projectId:pr.data.id,sourceId:src.data.id,jobId:job.data.id})});const body=await response.json().catch(()=>({}));if(!response.ok){await supabase.from("processing_jobs").update({status:"failed",error_message:body.error||"Media worker unavailable"}).eq("id",job.data.id);await supabase.from("project_sources").update({status:"failed",error_message:body.error||"Media worker unavailable"}).eq("id",src.data.id);await supabase.from("projects").update({status:"ingest_failed"}).eq("id",pr.data.id);setUploadMsg(body.error||"The media worker is not connected yet.");setBusy(false);return}}catch(error){console.error(error);setUploadMsg(error?.message||"Could not authorize the processing job.");setBusy(false);return}setProgress(100);setUploadMsg("Link received. The actual video download has started.");await loadProjects(workspace.id);setBusy(false);setTimeout(()=>{setUpload(false);setUploadMsg("")},1200)}

