useEffect(()=>{document.documentElement.dataset.theme=theme;if(typeof window!=="undefined")localStorage.setItem("alpha.theme",theme)},[theme]);useEffect(()=>{if(!supabase){setAuthReady(true);return}let alive=true;supabase.auth.getSession().then(({data})=>{if(!alive)return;setUser(data?.session?.user||null);setAuthReady(true)}).catch(()=>{if(alive)setAuthReady(true)});const a=supabase.auth.onAuthStateChange((_e,s)=>{if(alive){setUser(s?.user||null);setAuthReady(true);if(s?.user)setLanding(false)}});return()=>{alive=false;a.data.subscription.unsubscribe()}},[]);
useEffect(()=>{if(!user)return;loadWorkspace(user)},[user]);useEffect(()=>{if(workspace){loadProjects(workspace.id);loadGroups(workspace.id);const key="alpha:onboarded:"+user?.id;setOnboarding(Boolean(user?.id&&typeof window!=="undefined"&&!localStorage.getItem(key)));supabase.from("workspace_members").select("role,can_export").eq("workspace_id",workspace.id).eq("user_id",user?.id).maybeSingle().then(({data})=>setAdminAccess(Boolean(data&&(data.role==="owner"||data.can_export))))}},[workspace,user]);
useEffect(()=>{if(!user||!workspace)return;let cancelled=false;const record=async()=>{try{const{data:{session}}=await supabase.auth.getSession();if(cancelled||!session?.access_token)return;await fetch("/api/activity",{method:"POST",headers:{"content-type":"application/json",authorization:"Bearer "+session.access_token},body:JSON.stringify({workspaceId:workspace.id,action:"workspace_view",metadata:{view}})});}catch{}};record();return()=>{cancelled=true}},[user?.id,workspace?.id,view]);const[promptProject,setPromptProject]=useState(null),[scheduleClip,setScheduleClip]=useState(null);useEffect(()=>{const p=e=>setPromptProject(e.detail);const s=e=>setScheduleClip(e.detail);window.addEventListener("alpha:prompt",p);window.addEventListener("alpha:schedule",s);return()=>{window.removeEventListener("alpha:prompt",p);window.removeEventListener("alpha:schedule",s)}},[]);
